// Fallback & Formatting Node for Structured Vision Schema
const input = $input.first().json;

return [{
  json: {
    roomType: input.roomType || 'living_room',
    existingStyle: input.existingStyle || 'Transitional / Dated Traditional',
    furnitureAndObjects: input.furnitureAndObjects || [
      { name: 'Sofa', category: 'seating', condition: 'worn', position: 'center', recommendation: 'replace' },
      { name: 'Coffee Table', category: 'table', condition: 'outdated', position: 'center', recommendation: 'replace' }
    ],
    colorPaletteDetected: input.colorPaletteDetected || {
      dominantWallColor: 'Warm Off-White (#F2EFE9)',
      floorColor: 'Medium Oak Hardwood (#A88454)',
      accentColors: ['Charcoal (#333333)', 'Muted Ochre (#C29853)']
    },
    architecturalElements: input.architecturalElements || {
      walls: 'Painted drywall in good condition',
      flooring: 'Natural oak hardwood',
      windows: { count: 2, naturalLight: 'ample' }
    },
    lightingAssessment: input.lightingAssessment || {
      naturalLight: 'high',
      existingFixtures: ['Ceiling flush mount'],
      lightingDeficiencies: 'Lacks task and accent light layers'
    },
    spatialCharacteristics: input.spatialCharacteristics || 'Rectangular layout with strong window focal point.'
  }
}];
